// ---- Build Profile (Sub-workflow A) ----
// Turns the raw sheet rows into a clean profile, with safe defaults.

const DEFAULTS = { peak_start: 9, peak_end: 12, time_factor: 1.0, energy: 'normal' };

const profileRow = $('Read Profile').all().map(i => i.json).find(r => r.peak_hours !== undefined) || {};
const taskRows = $('Read Tasks').all().map(i => i.json).filter(r => r.date && r.task);

// "09:30" -> 570 (minutes since midnight), empty -> null
const toMin = (t) => {
  const m = String(t ?? '').match(/^(\d{1,2}):(\d{2})/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
};
const num = (v) => {
  const n = parseFloat(String(v ?? '').replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};

// Peak hours, stored as "9-12"
let peak_start = DEFAULTS.peak_start;
let peak_end = DEFAULTS.peak_end;
const pm = String(profileRow.peak_hours ?? '').match(/^(\d{1,2})\s*-\s*(\d{1,2})$/);
if (pm && Number(pm[2]) > Number(pm[1])) {
  peak_start = Number(pm[1]);
  peak_end = Number(pm[2]);
}

// Time factor, kept in a sane range
let time_factor = num(profileRow.time_factor);
if (time_factor === null || time_factor < 0.5 || time_factor > 3) time_factor = DEFAULTS.time_factor;

const recent_energy = ['low', 'normal', 'high'].includes(profileRow.recent_energy)
  ? profileRow.recent_energy
  : DEFAULTS.energy;

// Forbidden hours, stored as "12:00-14:00" or "12:00-14:00, 19:00-20:00"
const blocked_hours_raw = String(profileRow.blocked_hours ?? '').trim();
const blocked = blocked_hours_raw
  .split(',')
  .map(s => s.trim().match(/^(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})$/))
  .filter(Boolean)
  .map(m => ({ start: Number(m[1]) * 60 + Number(m[2]), end: Number(m[3]) * 60 + Number(m[4]) }))
  .filter(b => b.end > b.start);

// Last saved plan (used by /replan)
let last_plan = null;
try {
  last_plan = profileRow.last_plan_json ? JSON.parse(profileRow.last_plan_json) : null;
} catch (e) {
  last_plan = null;
}

// Clean task rows
const rows = taskRows.map(r => ({
  row_number: r.row_number,
  date: String(r.date),
  task: String(r.task).trim().toLowerCase(),
  category: ['deep', 'light', 'outdoor'].includes(r.category) ? r.category : 'light',
  planned_start: toMin(r.planned_start),
  planned_end: toMin(r.planned_end),
  planned_min: num(r.planned_min),
  actual_start: toMin(r.actual_start),
  actual_end: toMin(r.actual_end),
  actual_min: num(r.actual_min),
  status: r.status || 'planned',
}));

const today = $now.toFormat('yyyy-MM-dd');

return [{
  json: {
    peak_start,
    peak_end,
    peak_hours: `${peak_start}-${peak_end}`,
    time_factor,
    recent_energy,
    blocked,
    blocked_hours_raw,
    last_plan,
    today: today,
    today_planned: rows.filter(r => r.date === today && r.status === 'planned'),
    history: rows.filter(r => r.status === 'done' && r.planned_min && r.actual_min).slice(-50),
    has_history: rows.some(r => r.status === 'done'),
  },
}];
